"use strict";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import CreatingPoolInfo from "components/CreatingPoolInfo/CreatingPoolInfo";
import { LiquidityPositionInfoBadges } from "components/Liquidity/LiquidityPositionInfoBadges";
import { getProtocolVersionLabel } from "components/Liquidity/utils";
import { DoubleCurrencyLogo } from "components/Logo/DoubleLogo";
import { useGaugeForPool, useAvailableGauges } from "hooks/useGaugeData";
import {
  useCreatePositionContext,
  useDepositContext,
  usePriceRangeContext
} from "pages/Pool/Positions/create/CreatePositionContext";
import { DisplayCurrentPrice } from "pages/Pool/Positions/create/RangeSelectionStep";
import { Container } from "pages/Pool/Positions/create/shared";
import { PositionFlowStep } from "pages/Pool/Positions/create/types";
import { useCallback, useMemo } from "react";
import { Flex, Text, useMedia } from "ui/src";
import { GoldenVerified } from "ui/src/components/icons";
import { iconSizes } from "ui/src/theme";
const EditStep = ({ children, onClick, ...rest }) => {
  return <Container
    row
    onPress={onClick}
    gap="$gap24"
    justifyContent="space-between"
    alignItems="center"
    transition="background-color 0.2s ease"
    cursor="pointer"
    hoverStyle={{ backgroundColor: "$surface1Hovered" }}
    {...rest}
  >
      {children}
    </Container>;
};
export const EditSelectTokensStep = (props) => {
  const { setStep, derivedPositionInfo, positionState } = useCreatePositionContext();
  const { reset: resetPriceRangeState } = usePriceRangeContext();
  const { reset: resetDepositState } = useDepositContext();
  const { creatingPoolOrPair, currencies, protocolVersion, defaultInitialPrice, poolId } = derivedPositionInfo;
  const { fee, hook, poolType } = positionState;
  const [token0, token1] = currencies;
  const versionLabel = getProtocolVersionLabel(protocolVersion);
  const media = useMedia();
  const { hasGauge: v3HasGauge } = useGaugeForPool(poolId);
  const { data: availableGauges } = useAvailableGauges();
  const v2HasGauge = useMemo(() => {
    if (poolId || !token0 || !token1 || !availableGauges || protocolVersion !== ProtocolVersion.V2) {
      return false;
    }
    const token0Address = (token0.isNative ? token0.wrapped.address : token0.address).toLowerCase();
    const token1Address = (token1.isNative ? token1.wrapped.address : token1.address).toLowerCase();
    const isStable = poolType?.stable || false;
    return availableGauges.some((gauge) => {
      if (!gauge.token0 || !gauge.token1) return false;
      const gaugeToken0Address = (gauge.token0.address || gauge.token0.id || "").toLowerCase();
      const gaugeToken1Address = (gauge.token1.address || gauge.token1.id || "").toLowerCase();
      const tokensMatch = token0Address === gaugeToken0Address && token1Address === gaugeToken1Address || token0Address === gaugeToken1Address && token1Address === gaugeToken0Address;
      const stableMatch = (gauge.stable || false) === isStable;
      console.log("\u{1F504} V2 Gauge Check:", {
        gaugeId: gauge.id,
        tokensMatch,
        gaugeStable: gauge.stable,
        poolStable: isStable,
        stableMatch,
        poolType: gauge.poolType,
        isAlive: gauge.isAlive
      });
      return tokensMatch && gauge.poolType === "V2" && gauge.isAlive && stableMatch;
    });
  }, [poolId, token0, token1, availableGauges, protocolVersion, poolType]);
  const hasGauge = poolId ? v3HasGauge : v2HasGauge;
  console.log("\u{1F527} V2 Debug - EditStep:", {
    poolId,
    hasGauge,
    v3HasGauge,
    v2HasGauge,
    protocolVersion,
    token0Symbol: token0?.symbol,
    token1Symbol: token1?.symbol,
    poolType: poolType?.label
  });
  const handleEdit = useCallback(() => {
    resetPriceRangeState();
    resetDepositState();
    setStep(PositionFlowStep.SELECT_TOKENS_AND_FEE_TIER);
  }, [resetDepositState, resetPriceRangeState, setStep]);
  return <EditStep onClick={handleEdit} {...props}>
      <Flex gap="$gap12" flex={1}>
        <Flex row gap="$gap12">
          <DoubleCurrencyLogo currencies={[token0, token1]} size={media.md ? iconSizes.icon44 : iconSizes.icon32} />
          <Flex
    row
    gap="$gap8"
    alignItems="center"
    $md={{ flexDirection: "column", gap: "$gap4", alignItems: "flex-start" }}
  >
            <Flex row gap="$gap2" alignItems="center">
              <Text variant="subheading1">{token0?.symbol}</Text>
              <Text variant="subheading1">/</Text>
              <Text variant="subheading1">{token1?.symbol}</Text>
            </Flex>
            {hasGauge && <GoldenVerified size={iconSizes.icon18} />}
            <Flex row gap={2} alignItems="center">
              <LiquidityPositionInfoBadges
    size="small"
    versionLabel={versionLabel}
    v4hook={hook}
    feeTier={protocolVersion === ProtocolVersion.V2 ? void 0 : fee.feeAmount}
    poolType={protocolVersion === ProtocolVersion.V2 ? poolType.stable ? "stable" : "volatile" : void 0}
  />
            </Flex>
          </Flex>
        </Flex>
        {creatingPoolOrPair ? <CreatingPoolInfo /> : derivedPositionInfo.protocolVersion === ProtocolVersion.V2 ? <DisplayCurrentPrice price={defaultInitialPrice} /> : null}
      </Flex>
    </EditStep>;
};
